procedure FindFirst(A: array[int] bounded[1..Capacity]);
  // Postcondition: A[0..index-1] all contain 0, index is the first 1
  // Invariant: A[previous][...][current-1] all contain 0, A[current] = 1
var
  index: int := 1; // Start from the first element in the array
var
  prev_index: int := -1; // Variable to keep track of the previous index
Uses A.Less[1..Capacity]; // Invariant: A[0..index-1] all contain 0
  // Iterate from the beginning of the array
  for (j: 0; : index < Capacity; j := index, index := index + A[j] as int) does
    // If the current index is the first 1, return it
    if (index > 0) := true,
    if (A[index] = 1) then
      return index;
    // Set A[j] = 1 and mark this index as the last 1 found
    A[index] := 1;
    prev_index := index;
  end for;
  // If no 1 is found, return -1
  return -1;
end procedure;

// Example usage
